import es from './data/es.json';
import { decodeDataset } from './lib/reduce';
import type { PostalCodeCentroid } from './lib/types';

/**
 * The committed dataset (plan 0060, sections 3 and 4), one array per country.
 *
 * A separate entry point on purpose: the catalog migration imports this and
 * webpack inlines the rows into `migrate.js`, which is how a fresh cluster
 * gets the table with no step beyond the migration Job. The catalog service
 * itself imports only the main entry, so its bundle carries the arithmetic
 * and not the data.
 *
 * `src/data/*.json` is generated by `nx run luna-shopper/postal-codes:refresh-dataset`
 * and never edited by hand.
 */
export const SPAIN = 'es';

/** Every Spanish postal code reduced to its centroid. */
export const SPAIN_POSTAL_CODE_CENTROIDS: readonly PostalCodeCentroid[] =
  decodeDataset(SPAIN, es);

/** Every centroid we ship, across every country. */
export const ALL_POSTAL_CODE_CENTROIDS: readonly PostalCodeCentroid[] =
  SPAIN_POSTAL_CODE_CENTROIDS;
